  --bg: #f6f7f9;
  --surface: #ffffff;
  --text: #0f172a;
  --muted: #64748b;
  --border: #e5e7eb;
  --primary: #4f46e5;
  --danger: #dc2626;
  --danger-hover: #b91c1c;
  --shadow-sm: 0 1px 2px rgba(15, 23, 42, .06), 0 1px 3px rgba(15, 23, 42, .08);
  --shadow-lg: 0 20px 40px -12px rgba(15, 23, 42, .25), 0 8px 16px -8px rgba(15, 23, 42, .15);
  --radius: 12px;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Inter, Roboto, "Helvetica Neue", Arial, sans-serif;
  font-size: 15px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

a { color: inherit; }

/* Topbar */
.topbar {
  display: flex;
  align-items: center;
  gap: 32px;
  padding: 14px 28px;
  background: var(--surface);
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  z-index: 10;
}
.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  font-weight: 650;
  letter-spacing: -0.01em;
}
.logo {
  width: 24px; height: 24px; border-radius: 7px;
  background: linear-gradient(135deg, #6366f1, #ec4899);
  box-shadow: var(--shadow-sm);
}
.nav { display: flex; gap: 6px; flex: 1; }
.nav-link {
  text-decoration: none;
  padding: 7px 12px;
  border-radius: 8px;
  color: var(--muted);
  font-weight: 500;
}
.nav-link:hover { background: #f1f5f9; color: var(--text); }
.nav-link.active { background: #eef2ff; color: var(--primary); }
.avatar {
  width: 34px; height: 34px; border-radius: 50%;
  background: #0f172a; color: #fff;
  display: grid; place-items: center;
  font-size: 12px; font-weight: 600;
}

/* Page */
.page {
  max-width: 960px;
  margin: 32px auto;
  padding: 0 24px 64px;
}

.crumbs {
  display: flex; align-items: center; gap: 8px;
  color: var(--muted); font-size: 13px;
  margin-bottom: 16px;
}
.crumbs a { text-decoration: none; }
.crumbs a:hover { color: var(--text); }
.crumbs .sep { opacity: .5; }
.crumbs .current { color: var(--text); font-weight: 500; }

/* Preview card */
.preview {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 16px;
  box-shadow: var(--shadow-sm);
  overflow: hidden;
}
.frame { margin: 0; }
.frame img {
  display: block;
  width: 100%;
  height: auto;
  max-height: 560px;
  object-fit: cover;
  background: #0f172a;
}
.frame-fallback {
  display: grid; place-items: center;
  height: 360px;
  background: linear-gradient(135deg, #0f172a, #1e293b);
  color: #cbd5e1;
  font-size: 14px;
}
.meta {
  display: flex; align-items: flex-start; justify-content: space-between;
  gap: 16px; padding: 20px 24px;
  border-top: 1px solid var(--border);
}
.title {
  margin: 0 0 4px;
  font-size: 18px; font-weight: 650; letter-spacing: -0.01em;
}
.sub { margin: 0; color: var(--muted); font-size: 13px; }
.meta-tags { display: flex; gap: 6px; flex-wrap: wrap; }
.tag {
  padding: 4px 10px;
  background: #f1f5f9;
  color: #334155;
  border-radius: 999px;
  font-size: 12px; font-weight: 500;
}

/* Actions */
.actions {
  display: flex; gap: 8px; justify-content: flex-end;
  padding: 14px 24px 20px;
  border-top: 1px solid var(--border);
  background: #fafbfc;
}

.btn {
  display: inline-flex; align-items: center; gap: 8px;
  padding: 9px 14px;
  border-radius: 10px;
  border: 1px solid transparent;
  font: inherit; font-weight: 550;
  cursor: pointer;
  transition: background .15s, border-color .15s, transform .05s, box-shadow .15s;
  background: transparent;
  color: var(--text);
}
.btn:active { transform: translateY(1px); }
.btn:focus-visible {
  outline: 2px solid var(--primary);
  outline-offset: 2px;
}

.btn.ghost {
  background: var(--surface);
  border-color: var(--border);
}
.btn.ghost:hover { background: #f8fafc; border-color: #cbd5e1; }

.btn.danger {
  background: var(--danger);
  color: #fff;
  border-color: var(--danger);
  box-shadow: 0 1px 0 rgba(255,255,255,.15) inset, var(--shadow-sm);
}
.btn.danger:hover { background: var(--danger-hover); border-color: var(--danger-hover); }

/* Modal */
.modal[hidden] { display: none; }
.modal {
  position: fixed; inset: 0;
  z-index: 100;
  display: grid;
  place-items: center;
  padding: 20px;
}
.modal-backdrop {
  position: absolute; inset: 0;
  background: rgba(15, 23, 42, .55);
  backdrop-filter: blur(2px);
  animation: fade .18s ease-out;
}
.modal-panel {
  position: relative;
  width: min(440px, 100%);
  background: var(--surface);
  border-radius: 16px;
  padding: 28px 28px 22px;
  box-shadow: var(--shadow-lg);
  animation: pop .18s ease-out;
}
.modal-icon {
  width: 44px; height: 44px;
  border-radius: 50%;
  display: grid; place-items: center;
  background: #fee2e2;
  color: var(--danger);
  margin-bottom: 14px;
}
.modal-title {
  margin: 0 0 6px;
  font-size: 18px;
  font-weight: 650;
  letter-spacing: -0.01em;
}
.modal-desc {
  margin: 0 0 22px;
  color: var(--muted);
  font-size: 14px;
}
.modal-desc strong { color: var(--text); font-weight: 600; }
.modal-actions {
  display: flex; justify-content: flex-end; gap: 8px;
}
.modal-close {
  position: absolute; top: 12px; right: 12px;
  width: 30px; height: 30px;
  display: grid; place-items: center;
  background: transparent; border: 0;
  border-radius: 8px;
  color: var(--muted);
  cursor: pointer;
}
.modal-close:hover { background: #f1f5f9; color: var(--text); }

@keyframes fade { from { opacity: 0 } to { opacity: 1 } }
@keyframes pop {
  from { opacity: 0; transform: translateY(6px) scale(.98); }
  to   { opacity: 1; transform: none; }
}

/* Toast */
.toast {
  position: fixed;
  bottom: 24px; left: 50%;
  transform: translate(-50%, 20px);
  background: #0f172a;
  color: #fff;
  padding: 10px 16px;
  border-radius: 10px;
  font-size: 13.5px;
  box-shadow: var(--shadow-lg);
  opacity: 0;
  pointer-events: none;
  transition: opacity .2s, transform .2s;
  z-index: 200;
}
.toast.show {
  opacity: 1;
  transform: translate(-50%, 0);
}

@media (max-width: 560px) {
  .nav { display: none; }
  .meta { flex-direction: column; }
  .actions { flex-wrap: wrap; }
}
